SELECT,

  
    
      
      
      
    
  
  FALSE

AS can_view_details

WHERE t.enterprise_id = #{enterprise}
AND
  
    
    
    
  

AND t.created_at >= #{range.from} AND t.created_at <= #{range.to}
AND (LOCATE(#{filter.query}, t.tool_name) > 0 OR LOCATE(#{filter.query}, m.display_name) > 0)
AND t.actor_user_id = #{filter.actorUserId}
AND t.status = #{filter.status}
AND r.mode = #{filter.source}

  AND (t.created_at < #{cursor.time} OR (t.created_at = #{cursor.time} AND t.id < #{cursor.id}))

ORDER BY t.created_at DESC, t.id DESC LIMIT #{limit}
